### Environment-Based Configuration

```ts title="server/config.ts" icon="/icons/typescript.svg"
export const config = {
  development: process.env.NODE_ENV !== "production",
  port: process.env.PORT || 3000,
  database: {
    url: process.env.DATABASE_URL || "./dev.db",
  },
